body:
Notice `undef` being passed to the index field of the dxil op `dx.op.rawBufferLoad.i32`.  We should at least generate a warning or may even consider failing compilation.

**HLSL:**
```
struct S {
     uint v;
};

StructuredBuffer<S> stbuf;

uint main() : OUT
{
     int j;
     return stbuf[j].v;
}
```

**DXIL:**
```
define void @main() {
  %1 = call %dx.types.Handle @dx.op.createHandle(i32 57, i8 0, i32 0, i32 0, i1 false)  ; CreateHandle(resourceClass,rangeId,index,nonUniformIndex)
  %2 = call %dx.types.ResRet.i32 @dx.op.rawBufferLoad.i32(i32 139, %dx.types.Handle %1, i32 undef, i32 0, i8 1, i32 4)  ; RawBufferLoad(srv,index,elementOffset,mask,alignment)
  %3 = extractvalue %dx.types.ResRet.i32 %2, 0
  call void @dx.op.storeOutput.i32(i32 5, i32 0, i32 0, i8 0, i32 %3)  ; StoreOutput(outputSigId,rowIndex,colIndex,value)
  ret void
}
```
